cd /d/Temp/claude/3db4783c4b24ca36/fd501d7a-3e55-45ba-9bd0-80a39b24c9ec/scratchpad/labels; python -I - <<'EOF'
import re
def show(f,kws,w=600):
    t=open(f,encoding='utf-8').read()
    for kw in kws:
        ms=list(re.finditer(re.escape(kw),t,flags=re.I))
        print('##',f[:8],kw,len(ms))
        for m in ms[:2]:
            print('  ...',t[max(0,m.start()-150):m.start()+w]); 
        print()
show('telmi.txt',['8.1 Pregnancy Risk Summary','Fetal/Neonatal Adverse','Laboratory Tests','Creatinine'],700)
EOF

